pragma solidity >=0.8.0;

contract Base {
    uint256 public result;
    event BaseCalled(uint256 v);
    function f(uint256 x) public virtual returns (uint256) {
        result = x + 1;
        emit BaseCalled(x);
        return result;
    }
}

contract Child is Base {
    event OverrideCalled(uint256 v);
    event OverloadCalled(uint256 a, uint256 b);
    function f(uint256 x) public override returns (uint256) {
        result = x + 100;
        emit OverrideCalled(x);
        return result;
    }
    function f(uint256 x, uint256 y) public returns (uint256) {
        result = x + y;
        emit OverloadCalled(x, y);
        return result;
    }
    function callSelf1(uint256 x) public returns (uint256) {
        return this.f(x);
    }
    function callSelf2(uint256 x, uint256 y) public returns (uint256) {
        return this.f(x, y);
    }
}
